import json

def generate_product_data(num_products=5):
    """Simulates generating product data, as Claude Code might.
    In a real scenario, this would involve complex logic or API calls.
    """
    products = []
    for i in range(num_products):
        product = {
            "id": i + 1,
            "name": f"Product {i+1}",
            "description": f"A high-quality product, generated by AI.",
            "price": round(10.0 + i * 2.5, 2),
            "stock": 100 - i * 5
        }
        products.append(product)
    return products

def simulate_cart_operations(products):
    """Simulates basic cart operations, mimicking AI-generated logic.
    This part would typically be handled by a backend framework.
    """
    cart = []
    print("--- Simulating Cart Operations ---")

    # Add items to cart
    if products:
        item_to_add = products[0]
        cart.append({"product_id": item_to_add['id'], "quantity": 2})
        print(f"Added {item_to_add['name']} (x2) to cart.")

        item_to_add_2 = products[2]
        cart.append({"product_id": item_to_add_2['id'], "quantity": 1})
        print(f"Added {item_to_add_2['name']} (x1) to cart.")

    # Calculate total
    total_price = 0
    print("\n--- Cart Contents ---")
    for cart_item in cart:
        product = next((p for p in products if p['id'] == cart_item['product_id']), None)
        if product:
            item_total = product['price'] * cart_item['quantity']
            total_price += item_total
            print(f"- {product['name']} (x{cart_item['quantity']}): ${item_total:.2f}")
        else:
            print(f"- Unknown Product (ID: {cart_item['product_id']}) in cart.")

    print(f"\nTotal Cart Price: ${total_price:.2f}")
    return cart, total_price

def simulate_checkout(cart, total_price):
    """Simulates a simplified checkout process.
    In a real e-commerce site, this would involve payment gateways, order processing, etc.
    """
    print("\n--- Simulating Checkout ---")
    if total_price > 0:
        print("Checkout successful! Order placed.")
        print(f"Order details: {json.dumps({'cart': cart, 'total': total_price}, indent=2)}")
    else:
        print("Cart is empty. Cannot checkout.")

if __name__ == "__main__":
    print("--- E-commerce Site Simulation using Claude Code Principles ---")

    # 1. Product Generation (AI-assisted)
    # Claude Code could generate the structure and initial data for products.
    ecommerce_products = generate_product_data(num_products=3)
    print("\n--- Generated Products ---")
    print(json.dumps(ecommerce_products, indent=2))

    # 2. Core Functionality (AI-assisted logic)
    # Claude Code could generate the logic for cart management and calculations.
    user_cart, final_total = simulate_cart_operations(ecommerce_products)

    # 3. Checkout Process (AI-assisted flow)
    # Claude Code could outline or generate the basic steps for checkout.
    simulate_checkout(user_cart, final_total)

    print("\n--- Simulation Complete ---")
